// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        address originalOwner = c.owner();

        vm.prank(originalOwner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}
